cd /workspace/probe/fx && python3 - <<'EOF'
import struct
s=struct.unpack('<24i',open('wn.raw','rb').read())
u=[x%(2**32) for x in s]
M=2**32
def xs(x,a,b,c):
    x^=(x<<a)%M; x^=x>>b; x^=(x<<c)%M; return x%M
for (a,b,c) in [(13,17,5),(13,7,17),(5,17,13),(2,7,9),(11,19,8)]:
    if all(xs(u[i],a,b,c)==u[i+1] for i in range(23)): print("xorshift",a,b,c)
# xorshift with output = state after k advances? try double advance
def xs2(x): return xs(xs(x,13,17,5),13,17,5)
if all(xs2(u[i])==u[i+1] for i in range(23)): print("xorshift13,17,5 double")
# LCG on 31-bit: output = state>>1, i.e. v[i]=u[i]>>1? test LCG on v
v=[x>>1 for x in u]
import math
M31=2**31
d1=(v[0]-v[1])%M31; d2=(v[1]-v[2])%M31
g=math.gcd(d1,M31)
if d2%g==0:
    m=M31//g
    try:
        inv=pow(d1//g,-1,m); a0=(d2//g*inv)%m
        for k in range(g):
            a=a0+k*m; c=(v[1]-a*v[0])%M31
            if all((a*v[i]+c)%M31==v[i+1] for i in range(23)): print("LCG31 a=%d c=%d"%(a,c))
    except ValueError: pass
print("done")
EOF

cd /workspace/probe/fx && python3 - <<'EOF'
import struct, math
def rd(f):
    d=open(f,'rb').read(); return struct.unpack('<%di'%(len(d)//4),d)
S=2.0**31-1
def smp(x): 
    v=round(x*S)
    return max(-2**31,min(2**31-1,v))
N=16; rate=8000; T=N/rate; f1,f2=1000,3000
models={
 'sw1000_3000.raw': lambda n: math.sin(2*math.pi*(f1*n/rate + (f2-f1)*(n/rate)**2/(2*T))),
 'sw1000x3000.raw': lambda n: math.sin(2*math.pi*(f1*n/rate + (f2-f1)*(n/rate)**3/(3*T*T))),
 'sw1000d3000.raw': lambda n: math.sin(2*math.pi*f1*T/math.log(f2/f1)*(f2/f1)**(n/N)),
 'sw1000s3000.raw': lambda n: math.sin(2*math.pi*f1*(f2/f1)**(n/N)*n/rate),
}
for f,m in models.items():
    s=rd(f)
    bad=[(n,s[n],smp(m(n))) for n in range(N) if smp(m(n))!=s[n]]
    print(f, "mismatches:", len(bad), bad[:3])
EOF

